import{_ as o,l as d,o as e,c as i,v as t,p as l,x as r,d as n,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const m=JSON.parse('{"title":"DFS 与边分类","description":"","frontmatter":{"title":"DFS 与边分类","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/dfs-edge-types.md","filePath":"cs/dfs-edge-types.md","lastUpdated":1789023840000}'),c={name:"cs/dfs-edge-types.md"};function f(u,a,S,_,D,E){const s=d("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="dfs-与边分类" tabindex="-1">DFS 与边分类 <a class="header-anchor" href="#dfs-与边分类" aria-label="Permalink to &quot;DFS 与边分类&quot;">​</a></h1><div class="epigraph"><p>深度优先的进出时刻把每条边标成树边、反向边、前向边或横叉边；环与否写在反向边上。</p><footer>—— 据 Tarjan, Depth-First Search and Linear Graph Algorithms, 1972；CLRS 第 22 章整理</footer></div><p>上一课<a href="/cs/bfs-unweighted">BFS 与无权最短路</a>用队列得到无权距离。本课不重做分层。缺口是：图上还有<strong>结构</strong>——有没有环、哪些边连回祖先、哪些边连到另一棵树上的点。栈式深入加上发现/完成时刻，才能给边分类。本课只钉 DFS 与四类边（无向图上收缩成树边与反向边）。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>BFS 树几乎不谈回边：同一层或邻层的非树边不回答「是否有向环」。缺口是时间戳：\\(u.d\\) 发现、\\(u.f\\) 完成，括号性质：两个区间要么嵌套要么不相交。树边进入白邻；反向边指向祖先（有向环的证据）；前向边指向已完成的真后代；横叉边指向既非祖先也非后代的已发现点。</p><p><a href="/cs/dag-repr">DAG 预备</a>说过无环可排序；本课给出检测：有向图有环当且仅当 DFS 发现反向边。拓扑序本身下一课才写。</p><h3 id="递归栈就是那条路" tabindex="-1">递归栈就是那条路 <a class="header-anchor" href="#递归栈就是那条路" aria-label="Permalink to &quot;递归栈就是那条路&quot;">​</a></h3><p>DFS 的灰色顶点链是当前从根到 \\(u\\) 的路径。指向灰色即反向。指向黑色则按时间戳分成前向与横叉。不要用「看起来像回头」的口语代替颜色与时刻。</p><p><span class="marginnote">Tarjan 用 DFS 做强连通与双连通；本课只取边分类与括号定理，强连通不展开。CLRS 22.3 的分类是后课拓扑、桥与割点的共同前置。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对每个白点开一次 <code>DFS-VISIT</code>：置发现时刻，扫邻接表，递归白邻（树边），最后置完成时刻。全图 \\(\\Theta(V+E)\\)。无向图：每条边只分类一次，非树边都是反向边（连祖先）。</p>',11)),(e(),l(h,null,{default:r(()=>[p(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20W%5B%22%E7%99%BD%E9%82%BB%22%5D%20--%3E%20TREE%5B%22%E6%A0%91%E8%BE%B9%22%5D%0A%20%20G%5B%22%E7%81%B0%E9%82%BB%22%5D%20--%3E%20BACK%5B%22%E5%8F%8D%E5%90%91%E8%BE%B9%22%5D%0A%20%20B%5B%22%E9%BB%91%E9%82%BB%22%5D%20--%3E%20FW%5B%22%E5%89%8D%E5%90%91%E6%88%96%E6%A8%AA%E5%8F%89%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>括号：\\(u\\) 是 \\(v\\) 祖先当且仅当 \\([v.d,v.f]\\subset[u.d,u.f]\\)。后课拓扑按完成时刻降序，依据就在这里。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>边分类依赖<strong>第一次</strong> DFS 森林。另一次不同的顶点序可以换树边集合，但「有无反向边」对有向环不变。无向图的横叉在标准分类里不出现，因为先发现的端点会把边当树边或反向边用掉。</p><p>不要把 BFS 的非树边叫反向边：那不是 DFS 时刻。两种遍历的树都是生成林，职责不同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不算最短路。不写强连通分量的第二次 DFS。不引入桥与割点的 low 值。有向图的横叉边不单独构成环。后课拓扑排序假定会看完成时刻或入度，不再从颜色讲起。</p><p>后课默认：DFS 给出 \\(d/f\\) 与边分类；有向环 \\(\\Leftrightarrow\\) 反向边。拓扑是下一课把 DAG 变成线性序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>DFS 用发现/完成时刻给边分类；括号嵌套即祖先。</li><li>有向环当且仅当存在反向边。</li><li>代价仍 \\(\\Theta(V+E)\\)；不给出距离。</li><li>出处：Tarjan, 1972；CLRS 第 22.3 节。</li></ul>',9))])}const T=o(c,[["render",f]]);export{m as __pageData,T as default};
